require_once __DIR__.'/../../includes/bootstrap.php';require_roles(['ADMIN','RESPONSABLE']);$db=Database::connection();$id=max(0,(int)($_GET['id']??$_POST['id']??0));$d=['compagnie_id'=>'','categorie_id'=>'','code_produit'=>'','nom'=>'','description'=>'','prime_base'=>'0','prime_minimale'=>'0','duree_mois'=>'12','statut'=>'actif','date_debut_validite'=>date('Y-m-d'),'date_fin_validite'=>''];$errors=[];$selected=[];
