<div class="form-shell wide"><div class="page-heading"><h1 class="h3"><?= e($title) ?></h1><a class="btn btn-outline-secondary" href="index.php">Retour</a></div><?php if($errors): ?><div class="alert alert-danger"><?= e(implode(' ',$errors)) ?></div><?php endif; ?><form method="post" class="card card-body needs-validation" novalidate><?= csrf_field() ?><input type="hidden" name="id" value="<?= $id ?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">Compagnie *</label><select class="form-select" name="compagnie_id" required><option value="">Sélectionner</option><?php foreach($compagnies as $c): ?><option value="<?= $c['id'] ?>" <?= (int)$d['compagnie_id']==(int)$c['id']?'selected':'' ?>><?= e($c['raison_sociale']) ?></option><?php endforeach ?></select></div><div class="col-md-6"><label class="form-label">Catégorie de risque *</label><select class="form-select" name="categorie_id" required><option value="">Sélectionner</option><?php foreach($categories as $c): ?><option value="<?= $c['id'] ?>" <?= (int)$d['categorie_id']==(int)$c['id']?'selected':'' ?>><?= e($c['libelle']) ?></option><?php endforeach ?></select></div><div class="col-md-4"><label class="form-label">Code *</label><input class="form-control" name="code_produit" value="<?= e($d['code_produit']) ?>" required></div><div class="col-md-8"><label class="form-label">Nom *</label><input class="form-control" name="nom" value="<?= e($d['nom']) ?>" required></div><div class="col-md-4"><label class="form-label">Prime de base (FCFA)</label><input type="number" min="0" step="1" class="form-control" name="prime_base" value="<?= e((string)$d['prime_base']) ?>"></div><div class="col-md-4"><label class="form-label">Prime minimale</label><input type="number" min="0" step="1" class="form-control" name="prime_minimale" value="<?= e((string)$d['prime_minimale']) ?>"></div><div class="col-md-4"><label class="form-label">Durée (mois)</label><input type="number" min="1" class="form-control" name="duree_mois" value="<?= e((string)$d['duree_mois']) ?>"></div><div class="col-md-4"><label class="form-label">Début de validité *</label><input type="date" class="form-control" name="date_debut_validite" value="<?= e($d['date_debut_validite']) ?>" required></div><div class="col-md-4"><label class="form-label">Fin de validité</label><input type="date" class="form-control" name="date_fin_validite" value="<?= e($d['date_fin_validite']) ?>"></div><div class="col-md-4"><label class="form-label">Statut</label><select class="form-select" name="statut"><option value="actif" <?= $d['statut']==='actif'?'selected':'' ?>>Actif</option><option value="inactif" <?= $d['statut']==='inactif'?'selected':'' ?>>Inactif</option></select></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="3"><?= e($d['description']) ?></textarea></div><div class="col-12"><label class="form-label fw-semibold">Garanties incluses</label><div class="guarantee-grid"><?php foreach($garanties as $g): ?><label class="form-check guarantee-option"><input class="form-check-input" type="checkbox" name="garanties[]" value="<?= $g['id'] ?>" <?= in_array((int)$g['id'],$selected,true)?'checked':'' ?>><span><strong><?= e($g['libelle']) ?></strong><small><?= e($g['code']) ?></small></span></label><?php endforeach ?></div><div class="form-text">Les plafonds et franchises détaillés seront paramétrés dans le moteur tarifaire.</div></div></div><div class="text-end mt-4"><button class="btn btn-primary">Enregistrer le produit</button></div></form></div><?php require __DIR__.'/../../includes/footer.php'; ?>
